-- Comprehensive global airport baseline (mwgg/Airports static extract).
-- Additive: preserves existing US rows; fills nulls; does not clobber trusted tz/coords.
-- Source: https://github.com/mwgg/Airports (static JSON). Not applied via ADB.

ALTER TABLE public.airports
  ADD COLUMN IF NOT EXISTS country text,
  ADD COLUMN IF NOT EXISTS region text,
  ADD COLUMN IF NOT EXISTS source text,
  ADD COLUMN IF NOT EXISTS resolved_at timestamptz;

UPDATE public.airports SET source = 'legacy_us_seed' WHERE source IS NULL;

-- Upsert global registry
ON CONFLICT (iata) DO UPDATE SET
  icao = COALESCE(public.airports.icao, EXCLUDED.icao),
  country = COALESCE(public.airports.country, EXCLUDED.country),
  region = COALESCE(public.airports.region, EXCLUDED.region),
  -- Do not clobber existing name/tz/lat/lon from US seed
  source = COALESCE(public.airports.source, EXCLUDED.source),
  resolved_at = COALESCE(public.airports.resolved_at, EXCLUDED.resolved_at);

-- Mark newly inserted rows (those still on baseline source) already set.
-- Existing US seed keeps legacy_us_seed unless it was null.

